// Helper to preserve original capitalization
function preserveCase(original: string, translated: string): string {
  if (!original || !translated) return translated
  if (original[0] === original[0].toUpperCase() && /[а-яА-ЯёЁ]/.test(original[0])) {
    return translated.charAt(0).toUpperCase() + translated.slice(1)
  }
  return translated
}

// 智能翻译函数 - 处理俄语到英语的专业翻译
export function translateRussianToEnglish(text: string): string {
  if (text === null || text === undefined) return ''
  if (typeof text !== 'string') return String(text)
  if (!text) return text

  // 1. 先检查精确匹配
  const trimmed = text.trim()
  if (ruEnDictionary[trimmed]) {
    return ruEnDictionary[trimmed]
  }

  let result = text

  // 2. 替换缩写（保留大小写）- 先处理长缩写
  const sortedAbbrs = Object.entries(ruEnAbbreviations).sort((a, b) => b[0].length - a[0].length)
  for (const [ru, en] of sortedAbbrs) {
    const regex = new RegExp(`(^|[\\s,;:()\\[\\]])${ru.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')}(?=[\\s,;:()\\[\\]]|$)`, 'g')
    result = result.replace(regex, `$1${en}`)
  }

  // 3. 短语替换（按长度降序，优先匹配长词，不区分大小写）
  // 使用单词边界避免部分匹配（如"тока"不应在"протоколы"中匹配）
  const sortedPhrases = [...ruEnPhraseReplacements].sort((a, b) => b[0].length - a[0].length)
  for (const [ru, en] of sortedPhrases) {
    // Skip single-character words (too many false matches), but allow 2+ char words
    if (ru.length < 2) continue
    const escaped = ru.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')
    // For Cyrillic-only words, use lookbehind/lookahead for non-Cyrillic boundaries
    // For mixed/Latin phrases, use standard word boundaries
    const isCyrillic = /^[а-яА-ЯёЁ\s–—-]+$/.test(ru)
    let regex: RegExp
    if (isCyrillic) {
      // Boundary: start of string or non-Cyrillic/non-letter before, non-Cyrillic/non-letter after
      regex = new RegExp(`(^|[^а-яА-ЯёЁa-zA-Z])${escaped}(?=[^а-яА-ЯёЁa-zA-Z]|$)`, 'gi')
      result = result.replace(regex, `$1${en}`)
    } else {
      regex = new RegExp(`\\b${escaped}\\b`, 'gi')
      result = result.replace(regex, en)
    }
  }

  // 4. Stem-based fallback for remaining Cyrillic words
  // Russian is highly inflected; try stripping common endings and look up dictionary
  const russianCaseEndings = [
    // Noun/adjective case endings (longest first)
    'иями', 'иями', 'ами', 'ями', 'ого', 'его', 'ому', 'ему', 'ыми', 'ими',
    'ой', 'ей', 'ом', 'ем', 'ам', 'ям', 'ах', 'ях', 'ов', 'ев', 'ей',
    'ую', 'юю', 'ая', 'яя', 'ое', 'ее', 'ые', 'ие',
    'и', 'ы', 'а', 'я', 'у', 'ю', 'о', 'е', 'ь',
    // Verb endings (present/future tense)
    'уешь', 'юешь', 'ешь', 'ишь', 'ете', 'ёте', 'ут', 'ют', 'ет', 'ит',
    'ем', 'ём', 'у', 'ю', 'и', 'ь',
    // Verb past tense endings
    'нула', 'нуло', 'нули', 'нула', 'лся', 'лась', 'лось', 'лись',
    'ала', 'яло', 'яли', 'ала', 'ыл', 'ыла', 'ыло', 'ыли',
    'ил', 'ила', 'ило', 'или', 'ел', 'ела', 'ело', 'ели',
    'ул', 'ула', 'уло', 'ули', 'ял', 'яла', 'яло', 'яли',
    // Imperative endings
    'айте', 'ейте', 'ите', 'ь', 'й',
    // Short adjective endings
    'ен', 'ена', 'ено', 'ены',
    // Reflexive particle
    'ся', 'сь',
  ]
  result = result.replace(/[а-яА-ЯёЁ]+/g, (word) => {
    // Skip if already translated (contains Latin chars)
    if (/[a-zA-Z]/.test(word)) return word
    const lower = word.toLowerCase()
    // Try exact dictionary lookup first
    if (ruEnDictionary[lower]) return preserveCase(word, ruEnDictionary[lower])
    // Try stripping endings (recursive up to 2 levels)
    const tryStem = (w: string, depth: number): string | null => {
      if (depth > 2) return null
      for (const ending of russianCaseEndings) {
        if (w.length > ending.length + 2 && w.endsWith(ending)) {
          const stem = w.slice(0, -ending.length)
          if (ruEnDictionary[stem]) return ruEnDictionary[stem]
          // Also try stem + soft sign
          if (ruEnDictionary[stem + 'ь']) return ruEnDictionary[stem + 'ь']
          // Recursive
          const found = tryStem(stem, depth + 1)
          if (found) return found
        }
      }
      return null
    }
    const translated = tryStem(lower, 0)
    if (translated) return preserveCase(word, translated)
    return word
  })

  // 5. Handle "Label: Value" parameter lines - translate the label part
  result = result.replace(/^([^:]{2,60}):\s*(.+)$/gm, (match, label, value) => {
    const cleanLabel = label.trim()
    if (/[а-яА-ЯёЁ]/.test(cleanLabel)) {
      const translated = translateRussianToEnglish(cleanLabel)
      // Convert Russian decimal comma to period in numeric values
      let translatedValue = value.trim()
      // Only convert comma in number contexts: digits,digits followed by unit or end
      translatedValue = translatedValue.replace(/(\d),(\d)/g, '$1.$2')
      return `${translated}: ${translatedValue}`
    }
    return match
  })

  // 6. Convert Russian decimal comma to period (e.g., "4,2 В" → "4.2 V")
  // But be careful not to convert list commas (e.g., "2.5, 5, 10")
  result = result.replace(/(\d),(\d)/g, '$1.$2')

  // 7. Clean up extra spaces
  result = result
    .replace(/\s+/g, ' ')
    .replace(/\s,/g, ',')
    .replace(/\s\./g, '.')
    .replace(/\s:/g, ':')
    .trim()

  // 8. Capitalize first letter if result starts with lowercase
  if (result.length > 0 && /[a-z]/.test(result[0])) {
    result = result.charAt(0).toUpperCase() + result.slice(1)
  }

  return result
}

// Translate a single line of text (for <br> separated parameter lists)
function translateLine(line: string): string {
  const trimmed = line.trim()
  if (!trimmed) return line

  // Skip pure numbers/symbols
  if (!/[а-яА-ЯёЁ]/.test(trimmed)) return line

  // Check if it's a "Label: Value" line
  const colonIdx = trimmed.indexOf(':')
  if (colonIdx > 1 && colonIdx < 80) {
    const label = trimmed.substring(0, colonIdx).trim()
    const value = trimmed.substring(colonIdx + 1).trim()

    // Translate label
    let translatedLabel = label
    if (ruEnDictionary[label]) {
      translatedLabel = ruEnDictionary[label]
    } else if (/[а-яА-ЯёЁ]/.test(label)) {
      translatedLabel = translateRussianToEnglish(label)
    }

    // For value, translate any Russian words but keep numbers/units
    let translatedValue = value
    if (/[а-яА-ЯёЁ]/.test(value)) {
      translatedValue = translateRussianToEnglish(value)
    }

    return `${translatedLabel}: ${translatedValue}`
  }

  // Regular text line
  return translateRussianToEnglish(trimmed)
}

// Translate HTML content - preserves tags, translates text nodes
export function translateRussianHtml(html: string): string {
  if (!html) return html

  let result = html

  // Fix WordPress video shortcodes: convert <video><a href="url.mp4">url</a></video>
  // to standard HTML5 <video><source src="url.mp4" type="video/mp4"></video>
  result = result.replace(
    /<video([^>]*)>([\s\S]*?)<\/video>/gi,
    (match, attrs, inner) => {
      // Extract width/height from attributes
      const widthMatch = attrs.match(/width=["']?(\d+)/i)
      const heightMatch = attrs.match(/height=["']?(\d+)/i)
      const width = widthMatch ? widthMatch[1] : '640'
      const height = heightMatch ? heightMatch[1] : '360'

      // Extract video URL from <a href> inside
      const hrefMatch = inner.match(/<a[^>]*href=["']([^"']+\.(?:mp4|webm|ogg)[^"']*)["'][^>]*>/i)
      if (hrefMatch) {
        const videoUrl = hrefMatch[1]
        const ext = videoUrl.match(/\.(mp4|webm|ogg)/i)?.[1]?.toLowerCase() || 'mp4'
        const mimeType = ext === 'webm' ? 'video/webm' : ext === 'ogg' ? 'video/ogg' : 'video/mp4'
        return `<video width="${width}" height="${height}" controls preload="metadata" class="w-full max-w-2xl rounded-lg my-4 bg-black">
          <source src="${videoUrl}" type="${mimeType}">
          Your browser does not support the video tag.
        </video>`
      }
      return match
    }
  )

  // First, handle <br> separated parameter lists - these are very common in product descriptions
  // Split by <br>, translate each line, rejoin
  result = result.replace(/((?:[^<>]|<br\s*\/?>)+)/gi, (match) => {
    if (/<br\s*\/?>/i.test(match)) {
      const parts = match.split(/(<br\s*\/?>)/i)
      return parts.map(part => {
        if (/^<br/i.test(part)) return part
        if (!part || !/[а-яА-ЯёЁ]/.test(part)) return part
        return translateLine(part)
      }).join('')
    }
    return match
  })

  // Handle text between > and < (text nodes)
  result = result.replace(/>([^<]+)</g, (match, text) => {
    const trimmed = text.trim()
    if (!trimmed) return match
    if (!/[а-яА-ЯёЁ]/.test(trimmed)) return match
    // Skip if it's just numbers, symbols, or English
    if (/^[\d\s\W.,;:!?()\[\]{}'"\/\\-]+$/.test(trimmed)) return match
    const translated = translateLine(trimmed)
    return '>' + text.replace(trimmed, translated) + '<'
  })

  // Also translate alt and title attributes
  result = result.replace(/(alt|title)="([^"]*[а-яА-ЯёЁ][^"]*)"/g, (match, attr, text) => {
    const translated = translateRussianToEnglish(text)
    return `${attr}="${translated}"`
  })

  // Final safety net: translate any remaining Cyrillic words in text nodes
  // This catches text that might have been missed by the >...< regex due to complex HTML
  result = result.replace(/>([^<]*[а-яА-ЯёЁ][^<]*)</g, (match, text) => {
    const translated = translateRussianToEnglish(text)
    return '>' + translated + '<'
  })

  return result
}
